function initTabNavigation(){const e=document.querySelectorAll(".asir-tab-btn"),n=document.querySelectorAll(".asir-section");function t(t){e.forEach(e=>{const n=e.dataset.tab===t;e.classList.toggle("active",n),e.setAttribute("aria-selected",n?"true":"false")}),n.forEach(e=>{const n=e.id===t;e.classList.toggle("active",n)}),history.pushState?history.pushState(null,null,`#${t}`):location.hash=`#${t}`}e.forEach(e=>{e.addEventListener("click",()=>{t(e.dataset.tab)})});const i=window.location.hash.replace("#","");i&&document.getElementById(i)&&t(i)}function renderOverview(){const e=document.getElementById("overview-content");if(!e||"undefined"==typeof ASIRGARH_DATA)return;const{overview:n}=ASIRGARH_DATA;e.innerHTML=`\n        <div class="overview-layout">\n            <div class="overview-main-card">\n                <h3>🏰 The Impregnable Gateway</h3>\n                <p class="overview-prose">${n.summary}</p>\n                \n                <div class="overview-grid-cards">\n                    <div class="overview-subcard">\n                        <h4><span>📍</span> Geographical Position</h4>\n                        <p style="margin:0; font-size: 0.95rem; color: var(--asir-text-muted);">\n                            Situated in <strong>${n.location}</strong> at coordinates <strong>${n.coordinates}</strong>.\n                            Elevation of <strong>${n.elevation}</strong> with sheer vertical basalt drop.\n                        </p>\n                    </div>\n                    <div class="overview-subcard">\n                        <h4><span>👑</span> Heritage & Legacy</h4>\n                        <p style="margin:0; font-size: 0.95rem; color: var(--asir-text-muted);">\n                            Founded in the <strong>${n.builtEra}</strong> by <strong>${n.founders}</strong>.\n                            Spans <strong>${n.area}</strong>.\n                        </p>\n                    </div>\n                </div>\n            </div>\n\n            <div class="overview-side-panel">\n                <div class="info-box-widget">\n                    <h4>Quick Specifications</h4>\n                    <ul class="info-box-list">\n                        <li><span class="info-box-label">Native Name:</span> <span class="info-box-val">${n.nativeTitle}</span></li>\n                        <li><span class="info-box-label">Location:</span> <span class="info-box-val">Burhanpur, MP</span></li>\n                        <li><span class="info-box-label">Cliff Height:</span> <span class="info-box-val">${n.cliffHeight}</span></li>\n                        <li><span class="info-box-label">Key Pass:</span> <span class="info-box-val">Burhanpur Gap</span></li>\n                        <li><span class="info-box-label">Style:</span> <span class="info-box-val">Indo-Islamic / Hill Fort</span></li>\n                    </ul>\n                </div>\n\n                <div class="audio-guide-card">\n                    <h4>🎧 Audio Guide Simulation</h4>\n                    <p>Listen to an overview of Asirgarh's strategic role as the Gateway to the Deccan.</p>\n                    <button id="btn-audio-play" class="btn-audio-play">\n                        <span>▶️</span> Play Narration\n                    </button>\n                </div>\n            </div>\n        </div>\n    `}function initAudioGuide(){document.addEventListener("click",e=>{if(e.target&&("btn-audio-play"===e.target.id||e.target.closest("#btn-audio-play"))){const e=document.getElementById("btn-audio-play");if("speechSynthesis"in window)if(window.speechSynthesis.speaking)window.speechSynthesis.cancel(),e.innerHTML="<span>▶️</span> Play Narration";else{const n=new SpeechSynthesisUtterance("Welcome to Asirgarh Fort Explorer. Known as Kili-i-Dakkan, or the Key to the Deccan, Asirgarh stands atop a steep 750-meter mountain peak in Madhya Pradesh. Built originally by Asa Ahir in the 14th century and fortified by the Faruqui Dynasty and Mughals, Asirgarh commanded the strategic Burhanpur Gap—the primary land passage connecting Northern and Southern India.");n.rate=.95,n.onend=()=>{e.innerHTML="<span>▶️</span> Play Narration"},window.speechSynthesis.speak(n),e.innerHTML="<span>⏹️</span> Stop Narration"}else alert("Audio Speech Synthesis is not supported in this browser.")}})}function renderTimeline(){const e=document.getElementById("timeline-content");e&&"undefined"!=typeof ASIRGARH_DATA&&(e.innerHTML=`\n        <div class="timeline-container">\n            ${ASIRGARH_DATA.historyTimeline.map(e=>`\n                <div class="timeline-card">\n                    <div class="timeline-dot"></div>\n                    <span class="timeline-year-badge">${e.year}</span>\n                    <h3 class="timeline-card-title">${e.title}</h3>\n                    <div class="timeline-card-era">${e.era}</div>\n                    <p class="timeline-card-desc">${e.description}</p>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderBuilders(){const e=document.getElementById("builders-content");e&&"undefined"!=typeof ASIRGARH_DATA&&(e.innerHTML=`\n        <div class="builders-grid">\n            ${ASIRGARH_DATA.builders.map(e=>`\n                <div class="builder-card">\n                    <div class="builder-icon-box">${e.icon}</div>\n                    <h3 class="builder-name">${e.name}</h3>\n                    <div class="builder-role">${e.role}</div>\n                    <div class="builder-era">${e.era} • <em>${e.dynasty}</em></div>\n                    <p class="builder-desc">${e.description}</p>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderStrategicImportance(){const e=document.getElementById("strategic-content");if(!e||"undefined"==typeof ASIRGARH_DATA)return;const{strategicImportance:n}=ASIRGARH_DATA;e.innerHTML=`\n        <div class="strategic-wrapper">\n            <div class="strategic-visual">\n                <svg class="strategic-visual-svg" viewBox="0 0 500 350" xmlns="http://www.w3.org/2000/svg">\n                    <defs>\n                        <linearGradient id="satpuraGrad" x1="0%" y1="0%" x2="100%" y2="100%">\n                            <stop offset="0%" stop-color="#d35400" />\n                            <stop offset="100%" stop-color="#18202c" />\n                        </linearGradient>\n                    </defs>\n                    \x3c!-- Background Pass Lines --\x3e\n                    <path d="M 50,280 Q 250,140 450,280" fill="none" stroke="rgba(230,161,0,0.3)" stroke-width="2" stroke-dasharray="6,6" />\n                    \x3c!-- North to South Trade Arrow --\x3e\n                    <line x1="250" y1="30" x2="250" y2="320" stroke="#e6a100" stroke-width="4" marker-end="url(#arrow)" />\n                    \n                    \x3c!-- Mountain Shapes representing Satpura Range --\x3e\n                    <polygon points="20,280 120,120 200,280" fill="url(#satpuraGrad)" opacity="0.8" />\n                    <polygon points="300,280 380,120 480,280" fill="url(#satpuraGrad)" opacity="0.8" />\n                    \n                    \x3c!-- Central Asirgarh Peak --\x3e\n                    <polygon points="180,280 250,80 320,280" fill="#e6a100" opacity="0.9" />\n                    <rect x="235" y="70" width="30" height="20" fill="#c0392b" rx="3" />\n                    \n                    \x3c!-- Text Labels --\x3e\n                    <text x="250" y="45" fill="#ffffff" font-size="14" font-weight="bold" text-anchor="middle">NORTH INDIA (Agra / Malwa)</text>\n                    <text x="250" y="340" fill="#ffffff" font-size="14" font-weight="bold" text-anchor="middle">DECCAN PLATEAU (South India)</text>\n                    <text x="250" y="60" fill="#e6a100" font-size="12" font-weight="bold" text-anchor="middle">ASIRGARH FORT (750m)</text>\n                    <text x="250" y="210" fill="#f3e5ab" font-size="13" font-style="italic" text-anchor="middle">Burhanpur Gap (Pass)</text>\n                </svg>\n            </div>\n\n            <div class="strategic-points">\n                ${n.points.map(e=>`\n                    <div class="strategic-item">\n                        <div class="strategic-item-icon">${e.icon}</div>\n                        <div>\n                            <h4 class="strategic-item-title">${e.title}</h4>\n                            <p class="strategic-item-detail">${e.detail}</p>\n                        </div>\n                    </div>\n                `).join("")}\n            </div>\n        </div>\n    `}function renderArchitecture(e="all"){const n=document.getElementById("arch-grid");if(!n||"undefined"==typeof ASIRGARH_DATA)return;const t="all"===e?ASIRGARH_DATA.architecture:ASIRGARH_DATA.architecture.filter(n=>n.category.toLowerCase()===e.toLowerCase());n.innerHTML=t.map(e=>`\n        <div class="arch-card">\n            <img src="${e.image}" alt="${e.title}" class="arch-card-img" loading="lazy" />\n            <div class="arch-card-body">\n                <span class="arch-card-tag">${e.icon} ${e.category}</span>\n                <h3 class="arch-card-title">${e.title}</h3>\n                <p class="arch-card-desc">${e.description}</p>\n            </div>\n        </div>\n    `).join("");const i=document.querySelectorAll(".arch-filter-btn");i.forEach(e=>{e.addEventListener("click",()=>{i.forEach(e=>e.classList.remove("active")),e.classList.add("active"),renderArchitecture(e.dataset.filter)})})}function renderBattles(){const e=document.getElementById("battles-content");e&&"undefined"!=typeof ASIRGARH_DATA&&(e.innerHTML=`\n        <div class="battles-grid">\n            ${ASIRGARH_DATA.battles.map(e=>`\n                <div class="battle-card">\n                    <h3 class="battle-card-title">⚔️ ${e.title}</h3>\n                    <span class="battle-meta-tag">Duration: ${e.duration}</span>\n                    <div class="battle-detail-row"><strong>Combatants:</strong> ${e.combatants}</div>\n                    <div class="battle-detail-row"><strong>Result:</strong> ${e.result}</div>\n                    <p class="battle-summary">${e.summary}</p>\n                    <div class="battle-takeaway">💡 <strong>Historic Impact:</strong> ${e.keyTakeaway}</div>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderFacts(){const e=document.getElementById("facts-content");e&&"undefined"!=typeof ASIRGARH_DATA&&(e.innerHTML=`\n        <div class="facts-grid">\n            ${ASIRGARH_DATA.facts.map(e=>`\n                <div class="fact-card">\n                    <div class="fact-header">\n                        <span class="fact-icon">${e.icon}</span>\n                        <h4 class="fact-title">${e.title}</h4>\n                    </div>\n                    <p class="fact-desc">${e.description}</p>\n                </div>\n            `).join("")}\n        </div>\n    `)}function renderGallery(){const e=document.getElementById("gallery-grid");e&&"undefined"!=typeof ASIRGARH_DATA&&(e.innerHTML=ASIRGARH_DATA.gallery.map((e,n)=>`\n        <div class="gallery-item" data-index="${n}">\n            <img src="${e.image}" alt="${e.title}" loading="lazy" />\n            <div class="gallery-overlay">\n                <span class="gallery-cat">${e.category}</span>\n                <h4 class="gallery-title">${e.title}</h4>\n            </div>\n        </div>\n    `).join(""))}function initLightbox(){const e=document.getElementById("asir-lightbox"),n=document.getElementById("lightbox-img"),t=document.getElementById("lightbox-caption"),i=document.getElementById("lightbox-close");if(!e||"undefined"==typeof ASIRGARH_DATA)return;document.addEventListener("click",i=>{const a=i.target.closest(".gallery-item");if(a){const i=a.dataset.index,s=ASIRGARH_DATA.gallery[i];s&&(n.src=s.image,n.alt=s.title,t.textContent=`${s.title} — ${s.caption}`,e.classList.add("active"))}});const a=()=>{e.classList.remove("active")};i&&i.addEventListener("click",a),e.addEventListener("click",n=>{n.target===e&&a()}),document.addEventListener("keydown",n=>{"Escape"===n.key&&e.classList.contains("active")&&a()})}document.addEventListener("DOMContentLoaded",()=>{initTabNavigation(),renderOverview(),renderTimeline(),renderBuilders(),renderStrategicImportance(),renderArchitecture("all"),renderBattles(),renderFacts(),renderGallery(),initLightbox(),initQuiz(),initAudioGuide()});let currentQuizIdx=0,quizScore=0;function initQuiz(){document.getElementById("quiz-content")&&"undefined"!=typeof ASIRGARH_DATA&&renderQuizQuestion()}function renderQuizQuestion(){const e=document.getElementById("quiz-content"),n=ASIRGARH_DATA.quizQuestions;if(currentQuizIdx>=n.length)return e.innerHTML=`\n            <div style="text-align: center;">\n                <h3 style="font-family: var(--asir-font-heading); font-size: 2rem; color: var(--asir-gold);">🎉 Quiz Completed!</h3>\n                <p style="font-size: 1.2rem; margin: 1rem 0;">You scored <strong>${quizScore}</strong> out of <strong>${n.length}</strong>!</p>\n                <button id="btn-restart-quiz" class="btn-next-quiz">Try Again 🔄</button>\n            </div>\n        `,void document.getElementById("btn-restart-quiz").addEventListener("click",()=>{currentQuizIdx=0,quizScore=0,renderQuizQuestion()});const t=n[currentQuizIdx];e.innerHTML=`\n        <div style="font-size: 0.9rem; color: var(--asir-text-muted); margin-bottom: 0.5rem;">Question ${currentQuizIdx+1} of ${n.length}</div>\n        <h3 class="quiz-question-title">${t.question}</h3>\n        <div class="quiz-options">\n            ${t.options.map((e,n)=>`\n                <button class="quiz-opt-btn" data-opt="${n}">${e}</button>\n            `).join("")}\n        </div>\n        <div id="quiz-feedback" class="quiz-feedback"></div>\n        <button id="btn-next-q" class="btn-next-quiz" style="display: none;">Next Question ➔</button>\n    `;const i=e.querySelectorAll(".quiz-opt-btn"),a=document.getElementById("quiz-feedback"),s=document.getElementById("btn-next-q");i.forEach(e=>{e.addEventListener("click",()=>{i.forEach(e=>e.disabled=!0);parseInt(e.dataset.opt)===t.correct?(e.classList.add("correct"),quizScore++,a.className="quiz-feedback show",a.style.background="rgba(46, 204, 113, 0.15)",a.style.color="#2ecc71",a.style.border="1px solid #2ecc71",a.innerHTML=`<strong>Correct!</strong> ${t.explanation}`):(e.classList.add("wrong"),i[t.correct].classList.add("correct"),a.className="quiz-feedback show",a.style.background="rgba(231, 76, 60, 0.15)",a.style.color="#e74c3c",a.style.border="1px solid #e74c3c",a.innerHTML=`<strong>Incorrect.</strong> ${t.explanation}`),s.style.display="inline-block"})}),s.addEventListener("click",()=>{currentQuizIdx++,renderQuizQuestion()})}